<script setup>import pairs from '../data/history-pairs.json';const base=import.meta.env.BASE_URL</script>
<template><div class="stack"><div class="split" style="height:auto"><div class="col"><h2>FiveK · 5,000 originals</h2><div class="partition"><div style="flex:4">Experts A–D · train</div><div class="held" style="flex:1">Expert E<br>unseen</div></div><p class="small">Five expert-retouched versions per image</p></div><div class="col"><h2>PPSD</h2><div class="partition"><div style="flex:5">250 train users</div><div class="held" style="flex:1">50<br>unseen</div></div><p class="small">Training-free adaptation to held-out users</p></div></div><div class="rule"><div class="row spread"><h3>Eight historical pairs per query</h3><span class="small muted">Original + retouched image</span></div><div class="history-strip"><figure v-for="p in pairs.slice(0,8)" :key="p.id"><img :src="base+p.original" :alt="`Historical original ${p.id}`"/><img :src="base+p.edited" :alt="`Expert C edit ${p.id}`"/><figcaption>H{{Number(p.id)}} · C</figcaption></figure></div></div><p class="note">Fixed model parameters. No query ground truth at inference.</p></div></template>
